describe('Form Field Accessibility - Label Association', () => {
  beforeEach(() => {
    cy.visit('/form-page');
  });

  it('should have form fields with associated labels for screen reader users', () => {
    // Verify form is visible
    cy.get('[data-testid="form-container"]').should('be.visible');

    // Verify first input field has a label
    cy.get('[data-testid="first-name-input"]').should('be.visible');
    cy.get('[data-testid="first-name-label"]').should('contain', 'First Name');

    // Verify second input field has a label
    cy.get('[data-testid="last-name-input"]').should('be.visible');
    cy.get('[data-testid="last-name-label"]').should('contain', 'Last Name');

    // Verify email input field has a label
    cy.get('[data-testid="email-input"]').should('be.visible');
    cy.get('[data-testid="email-label"]').should('contain', 'Email Address');

    // Verify password input field has a label
    cy.get('[data-testid="password-input"]').should('be.visible');
    cy.get('[data-testid="password-label"]').should('contain', 'Password');

    // Verify confirm password field has a label
    cy.get('[data-testid="confirm-password-input"]').should('be.visible');
    cy.get('[data-testid="confirm-password-label"]').should('contain', 'Confirm Password');

    // Verify all labels are associated with their respective inputs
    cy.get('[data-testid="first-name-label"]').should('have.attr', 'for', 'first-name-input');
    cy.get('[data-testid="last-name-label"]').should('have.attr', 'for', 'last-name-input');
    cy.get('[data-testid="email-label"]').should('have.attr', 'for', 'email-input');
    cy.get('[data-testid="password-label"]').should('have.attr', 'for', 'password-input');
    cy.get('[data-testid="confirm-password-label"]').should('have.attr', 'for', 'confirm-password-input');

    // Verify form is accessible with screen reader
    cy.get('[data-testid="form-container"]').should('have.attr', 'aria-labelledby', 'first-name-label first-name-input');
    cy.get('[data-testid="form-container"]').should('have.attr', 'aria-describedby', 'first-name-label first-name-input');
  });

  it('should handle edge case where form field is missing a label', () => {
    // Intercept the API call to load form
    cy.intercept('GET', '/api/form-data').as('loadForm');
    cy.wait('@loadForm');

    // Verify form is loaded
    cy.get('[data-testid="form-container"]').should('be.visible');

    // Verify a field is missing a label
    cy.get('[data-testid="phone-input"]').should('be.visible');
    cy.get('[data-testid="phone-label"]').should('not.exist');

    // Verify screen reader still announces the field
    cy.get('[data-testid="phone-input"]').should('have.attr', 'aria-label', 'Phone Number');

    // Verify form is still accessible
    cy.get('[data-testid="form-container"]').should('have.attr', 'aria-labelledby', 'first-name-label first-name-input');
    cy.get('[data-testid="form-container"]').should('have.attr', 'aria-describedby', 'first-name-label first-name-input');

    // Verify error message is displayed for missing label
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Please provide a label for the phone field');
  });
});
